struct scope { struct scope *parent; struct entry **buckets; };   /* one hash per scope */
static struct scope *cur;                       /* current scope, outermost = file */
int  define(const char *name, struct symbol *sym) {   /* 0 = duplicate in this scope */
    return scope_insert(cur, name, sym) ? 1 : 0;
}
struct symbol *lookup(const char *name) {       /* innermost outward */
    for (struct scope *s = cur; s; s = s->parent)
        if (scope_find(s, name)) return scope_find(s, name);
    return NULL;                                /* unresolved */
}
void scope_open(void)  { cur = scope_new(cur); }      /* push a fresh scope */
void scope_close(void) { cur = cur->parent; }         /* pop; symbols live in an arena */
